230	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto) {
231	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
232	        validateRequiredFields(ownerFieldsDto);
233	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
234	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
235	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
236	        rejectDuplicateHousehold(ownerFieldsDto);
237	    }
238	
239	    /**
240	     * Builds the customer code assigned to a newly created owner. The code is formatted as
241	     * {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the upper-cased first three letters of
242	     * the owner's last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to
243	     * one more than the current number of owners. For example the seventh owner named
244	     * {@code 'Smith'} is assigned {@code 'SMI-0007'}.
245	     *
246	     * @param lastName the owner's last name
247	     * @return the formatted customer code
248	     */
249	    private String nextCustomerCode(String lastName) {
250	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
251	        long sequence = this.clinicService.findAllOwners().size() + 1L;
252	        return String.format("%s-%04d", last3, sequence);
253	    }
254	
255	    /**
256	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
257	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
258	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
259	     * the names of every offending field, which the exception advice renders as a 400 response
260	     * with an {@code errors} array.
261	     *
262	     * @param ownerFieldsDto the submitted owner fields
263	     */
264	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
265	        List<String> missing = new ArrayList<>();
266	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
267	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
268	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
269	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
270	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
271	        if (!missing.isEmpty()) {
272	            throw new RequiredFieldsMissingException(missing);
273	        }
274	    }
275	
276	    private void addIfBlank(List<String> missing, String fieldName, String value) {
277	        if (value == null || value.isBlank()) {
278	            missing.add(fieldName);
279	        }
280	    }
281	
282	    /**
283	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
284	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
285	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
286	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
287	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
288	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
289	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
290	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
291	     *
292	     * @param telephone the submitted telephone value
293	     * @return the normalized E.164 telephone
294	     */
295	    private String normalizeTelephone(String telephone) {
296	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
297	        String e164;
298	        if (cleaned.startsWith("+")) {
299	            e164 = "+" + cleaned.substring(1);
300	        } else {
301	            String national = cleaned;
302	            if (national.startsWith("0")) {
303	                national = national.substring(1);
304	            }
305	            e164 = "+61" + national;
306	        }
307	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
308	            throw new InvalidFieldsException(List.of("telephone"));
309	        }
310	        return e164;
311	    }
312	
313	    /**
314	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
315	     * and a domain containing at least one dot, none of the parts holding whitespace or a
316	     * second {@code @}.
317	     */
318	    private static final java.util.regex.Pattern EMAIL_PATTERN =
319	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
320	
321	    /**
322	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
323	     * accepted and returned unchanged. When present it must be a syntactically valid address;
324	     * the value is stored and returned lower-cased. When present but invalid an
325	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
326	     * response naming the {@code email} field.
327	     *
328	     * @param email the submitted email value, or {@code null} when omitted
329	     * @return the lower-cased email, or {@code null} when none was supplied
330	     */
331	    private String normalizeEmail(String email) {
332	        if (email == null) {
333	            return null;
334	        }
335	        String trimmed = email.trim();
336	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
337	            throw new InvalidFieldsException(List.of("email"));
338	        }
339	        return trimmed.toLowerCase(java.util.Locale.ROOT);
340	    }
341	
342	    /**
343	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
344	     * The telephone is stored in its normalized E.164 form, so a plain equality check
345	     * against every owner's telephone compares E.164 values. When a match is found a
346	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
347	     * 409 Conflict response.
